package run.ikaros.finance; import jakarta.validation.Valid; import java.time.Instant; import java.util.UUID; import org.springframework.web.bind.annotation.*; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; @RestController @RequestMapping("/api/v2/finance/ledgers/{ledgerId}/transactions") public class FinanceTransactionController{private final PersistentFinanceTransactionService service;public FinanceTransactionController(PersistentFinanceTransactionService s){service=s;}@PostMapping public Mono<TransactionView> create(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@Valid@RequestBody CreateTransactionRequest r){return service.create(a,ledgerId,r);}@GetMapping public Flux<TransactionView> list(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId){return service.list(a,ledgerId);}@GetMapping("/monthly")public Flux<TransactionView> month(@RequestHeader("X-Ikaros-Actor-Id")UUID a,@PathVariable UUID ledgerId,@RequestParam Instant from,@RequestParam Instant to){return service.month(a,ledgerId,from,to);}}
